public static String appx(String word1, String word2) {
    int len1 = word1.length();
    int len2 = word2.length();
    int sumLen = len1 + len2;
    // count letters
    Map<Character, Integer> freq1 = new HashMap<>();
    for (char c : word1.toCharArray()){
        freq1.put(c, freq1.getOrDefault(c, 0)+1);
    }
    Map<Character, Integer> freq2 = new HashMap<>();
    for (char c : word2.toCharArray()){
        freq2.put(c, freq2.getOrDefault(c, 0)+1);
    }
    int commonSum = 0;
    for (Map.Entry<Character, Integer> e: freq1.entrySet()){
        char c = e.getKey();
        if (freq2.containsKey(c)){
            commonSum += e.getValue() + freq2.get(c);
        }
    }
    // Simplify fraction commonSum / sumLen
    if (commonSum == 0){
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int gcd = gcd(commonSum, sumLen);
    int num = commonSum / gcd;
    int den = sumLen / gcd;
    String value;
    if (den == 1){
        value = String.valueOf(num);
    } else {
        value = num + "/" + den;
    }
    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

