public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) return false;
    // Special case when k is even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // For other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled when k even
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

