public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    stack.push(0);
    java.util.List<Integer> order = new java.util.ArrayList<>();
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int neighbor : graph[node]) {
            if (neighbor != parent[node]) {
                parent[neighbor] = node;
                stack.push(neighbor);
            }
        }
    }

    int total = 0;
    for (int i = order.size() - 1; i >= 0; i--) {
        int node = order.get(i);
        if (node != 0 && hasApple[node]) {
            total += 2; // traverse to node and back
        }
        if (node != 0) {
            hasApple[parent[node]] = hasApple[parent[node]] | hasApple[node];
        }
    }

    return total;
}

