public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";
    int[] freq = new int[65536];
    int total = 0;
    for (int i=0; i<s.length(); i++){
        char c = s.charAt(i);
        freq[c]++;
        total++;
    }
    StringBuilder sb = new StringBuilder(s.length());
    while (total > 0) {
        // forward ascending
        int last = -1;
        // find smallest char
        for (int i=0; i<freq.length; i++) {
            if (freq[i] > 0) {
                last = i;
                sb.append((char)i);
                freq[i]--;
                total--;
                break;
            }
        }
        if (last == -1) break; // no chars left
        // continue ascending > last
        while (true) {
            int next = -1;
            for (int i = last + 1; i < freq.length; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1 || total == 0) break;
            sb.append((char)next);
            freq[next]--;
            total--;
            last = next;
        }
        if (total == 0) break;
        // backward descending
        int prev = -1;
        for (int i = freq.length - 1; i >= 0; i--) {
            if (freq[i] > 0) {
                prev = i;
                sb.append((char)i);
                freq[i]--;
                total--;
                break;
            }
        }
        if (prev == -1) break;
        while (true) {
            int next = -1;
            for (int i = prev - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1 || total == 0) break;
            sb.append((char)next);
            freq[next]--;
            total--;
            prev = next;
        }
    }
    return sb.toString();
}

